-- First Chinese article translations (phase 6, final phase of the "all
-- six languages" rollout). Same 5 articles as the previous languages'
-- first batches -- Male Airport, the Gaafu Atoll fishing guide, fishing
-- techniques, fishing seasons, and "Where Is Maldives Located" -- keeping
-- coverage even across languages. Same conventions: canonical English
-- entity_id kept, own Chinese slug/title/body, internal links inside the
-- body still point at the English URLs (those verticals aren't translated
-- yet).
-- FIX (applied after discovering the bug): entity_id below is resolved via a
-- scalar subquery on the canonical English article slug, NOT a hardcoded
-- UUID literal. nodes.id is generated by gen_random_uuid() at insert time with
-- no explicit id column in the seeding migration, so the same article gets a
-- different random UUID in every database (local sandbox vs. production). A
-- literal UUID captured from one database's nodes table will never match row
-- in another, causing translations_entity_id_fkey violations. Resolving by
-- slug instead makes this migration portable across any database that has
-- run the legacy_articles seed migration.
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'male-airport-velana-international-airport'), 'article', 'zh', 'male-jichang-weilana-guoji-jichang', '马累机场 | 维拉纳国际机场', '了解关于马累机场（又名维拉纳国际机场）的一切，这是马尔代夫的主要空中门户。航班信息、设施等内容尽在此文。', null, '<h2>简介</h2><p>维拉纳国际机场，通常被称为<a href="/maldives/islands/male/">马累</a>机场，是通往马尔代夫令人惊叹的岛屿的主要国际门户。该机场位于胡鲁雷岛，靠近首都马累，是来自世界各地旅客的重要枢纽。凭借现代化设施、广泛的航线网络和一流的服务，马累机场在马尔代夫旅游业中发挥着至关重要的作用，每年接待数百万乘客。</p><p>马尔代夫以其天堂般的海滩、清澈的海水和豪华度假村而闻名。无论您是家庭度假、浪漫之旅，还是大胆的单人旅行，您的旅程都始于维拉纳国际机场。本指南将详细介绍您需要了解的有关马累机场的一切，包括其历史、设施、交通方式和旅行提示。</p><h4>快速导航</h4><p>机场概况 航班信息 设施与服务 交通与出行 维拉纳国际机场旅行提示 马尔代夫机场地图 马尔代夫机场可做的事情 马尔代夫机场列表 常见问题</p><h2>机场概况</h2><p>维拉纳国际机场（IATA代码：MLE，ICAO代码：VRMM）是马尔代夫最繁忙、最重要的机场，是外国游客和国内旅客的主要入境口岸。该机场战略性地位于首都马累附近的胡鲁雷岛，使其成为该地区航空连接的重要枢纽。</p><p>该机场最初名为胡鲁雷机场，于1960年开放，此后经历了多次扩建和现代化改造，以应对不断增长的马尔代夫游客数量。2017年，该机场更名为维拉纳国际机场，以纪念对马尔代夫发展做出重大贡献的第二任总统易卜拉欣·纳西尔。如今，维拉纳国际机场拥有最先进的设施，包括一条可容纳空客A380等世界最大飞机的新跑道。</p>', '马累机场 | 维拉纳国际机场 | 马尔代夫旅行指南 | MTG', '了解关于马累机场（又名维拉纳国际机场）的一切，这是马尔代夫的主要空中门户。航班信息、设施等内容尽在此文。', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'gaafu-atoll-fishing-guide-mfh-maamendhoo'), 'article', 'zh', 'gafu-huanjiao-diaoyu-mamenduo-zhuangzuo-baoyou-zhinan', '加夫环礁钓鱼：马门杜小屋与包船向导', '介绍我们在马尔代夫南部加夫阿利夫环礁马门杜岛自营小屋提供的包船船只、价格及多日套餐。', null, '<p>马门杜是马尔代夫南部加夫阿利夫环礁的一个岛屿，我们在此经营着自己的小屋，以及与之配套运营的包船业务。本指南介绍了围绕该业务打造的船只、包船价格和多日套餐。</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge.jpeg" alt="Maldives Fishing and Holidays Lodge，马门杜，加夫阿利夫环礁" loading="lazy" /></figure><h2>小屋</h2><p><a href="/maldives/guesthouses/maldives-fishing-and-holidays-lodge/">我们的小屋</a>是位于马门杜的一家民宿，每间客房最多可住两位客人，提供全食宿服务，由与钓鱼包船相同的运营商经营——因此住宿和钓鱼可以一站式预订，无需分开安排。</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge-hotel.jpeg" alt="Maldives Fishing and Holidays Lodge" loading="lazy" /></figure><h2>船只</h2><p>包船使用的是“Emperor”号——一艘32英尺长的钓鱼船，配备两台200马力舷外发动机，最多可搭载5名乘客。</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-charter-boat.webp" alt="马尔代夫钓鱼包船" loading="lazy" /></figure><h2>私人包船价格</h2><p>可直接预订两种私人包船，价格为每艘船的价格，而非每人价格：</p><ul><li><a href="/maldives/fishing/private-full-day-fishing-charter/">私人全天包船</a> ——每艘船起价1,380美元，约8小时。</li><li><a href="/maldives/fishing/private-half-day-fishing-charter/">私人半天包船</a> ——每艘船起价980美元，约4小时。</li></ul><h2>多日钓鱼套餐</h2><p>除了两种独立包船外，运营商还提供14种2晚至8晚的多日套餐，每种都可选择全天或半天的钓鱼形式，包含小屋住宿、往返国内航班、船只接送，以及相应天数的包船服务。价格根据1至5人的团体规模而有所不同，5人共享一艘船时人均价格最优惠。<a href="/maldives/packages/2-night-maldives-fishing-package-full-day-fishing/">2晚套餐</a>和<a href="/maldives/packages/8-night-maldives-fishing-package-full-day-fishing/">8晚套餐</a>代表了该范围的两端——完整的<a href="/maldives/packages/fishing/">钓鱼套餐列表</a>展示了所有可选的时长。</p><h2>如何前往</h2><p>围绕马门杜打造的套餐将往返国内航班与前往该岛的船只接送整合为套餐的一部分，无需单独安排。</p><h2>预订</h2><p>以上所有选项均可按需预订——请通过<a href="/maldives/providers/maldives-fishing-and-holiday/">运营商页面</a>与我们联系，或从适合您行程的包船或套餐页面开始预订。</p>', '加夫环礁钓鱼：马门杜小屋与包船向导 | 马尔代夫旅行指南 | MTG', '介绍我们在马尔代夫南部加夫阿利夫环礁马门杜岛自营小屋提供的包船船只、价格及多日套餐。', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-techniques-guide'), 'article', 'zh', 'maldives-diaoyu-jifa-tuoye-jiyi-poupin-shoulian', '马尔代夫钓鱼技巧：拖钓、路亚铁板、水面系拟饵钓和手线钓', '一份简明指南，介绍马尔代夫环礁中使用的主要钓鱼技巧——拖钓、路亚铁板、水面系拟饵钓和手线钓——以及每种技巧能钓到的鱼种。', null, '<p>在马尔代夫预订的大多数钓鱼行程都属于几种技巧之一，每种技巧适用于不同的鱼种和不同的水域。本指南将解释每种技巧的具体内容，以及您用它最可能钓到的鱼。</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/maldives-atoll-aerial-view.webp" alt="马尔代夫环礁航拍图" loading="lazy" /></figure><h2>拖钓</h2><p>拖钓是指在行驶中的船只后方拖拽装有拟饵或诱饵的鱼线，通常沿着洄游鱼类经过的环礁边缘或礁石陡坡进行。这是捕捞梭鱼——海洋中速度最快的鱼类之一，时速可达80公里——的标准技巧，也用于捕捞常在漂浮物附近出现的黄鳍金枪鱼和鲯鳅。</p><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="马尔代夫的梭鱼" loading="lazy" /></figure><h2>路亚铁板钓</h2><p>路亚铁板钓是在深水陡坡和礁石斜坡上方垂直操控一块有重量的金属拟饵，而非在拖钓适用的开阔水域进行。这种方法最常与牙带鱼联系在一起——它是一种栖息在此类水域中、单独行动且顽强的掠食性鱼类。</p><figure><img src="legacy/fishing/images/dogtooth-tuna-in-maldives.webp" alt="马尔代夫的牙带鱼" loading="lazy" /></figure><h2>水面系拟饵钓（Popping）</h2><p>水面系拟饵钓是将水面拟饵投向礁石边缘或水道，并以剧烈、飞溅的动作收线，以引诱鱼类从水面而非深处发起攻击。这种技巧与巨鲹的联系最为紧密，马尔代夫因盛产巨鲹而被国际公认为顶级钓场之一。</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/giant-trevally.webp" alt="在马尔代夫钓鱼中捕获的巨鲹" loading="lazy" /></figure><h2>手线钓与底钓</h2><p>手线钓是用卷线器、鱼线、鱼钩和鱼饵，以手动方式操作，而非抛投和收线，是入门门槛最低的传统技巧，通常作为无需经验的日落入门行程提供。这也是马尔代夫传统的竿线鲣鱼捕捞业的基础。与之密切相关的底钓技巧是在礁石结构上方抛锚钓鱼，是捕捞石斑鱼和笛鲷的常见方式。</p><figure><img src="legacy/images/fishing/tuna-fish-in-maldives.webp" alt="马尔代夫的鲣鱼" loading="lazy" /></figure><figure><img src="uploads/assets/uploads/fishing/images/gallery/reef-fishing-grouper.webp" alt="在马尔代夫礁石钓到的石斑鱼" loading="lazy" /></figure><h2>如何选择技巧</h2><p>如果您想要一次轻松随意的初次体验，手线钓或日落行程无需任何经验。如果您想捕获特定的战利品鱼种，技巧的选择取决于目标鱼类：梭鱼和金枪鱼用拖钓，牙带鱼用路亚铁板钓，巨鲹用水面系拟饵钓。我们从马门杜出发的<a href="/maldives/providers/maldives-fishing-and-holiday/">私人包船</a>使用“Emperor”号，涵盖拖钓和底钓——欢迎查看我们的<a href="/maldives/fishing/private-full-day-fishing-charter/">全天包船</a>页面，或浏览完整的<a href="/maldives/fishing/#fish-species">鱼种指南</a>，了解更多您可能钓到的鱼类。</p>', '马尔代夫钓鱼技巧：拖钓、路亚铁板、水面系拟饵钓和手线钓 | 马尔代夫旅行指南 | MTG', '一份简明指南，介绍马尔代夫环礁中使用的主要钓鱼技巧——拖钓、路亚铁板、水面系拟饵钓和手线钓——以及每种技巧能钓到的鱼种。', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-seasons-month-by-month-guide'), 'article', 'zh', 'maldives-diaoyu-jijie-zhuyue-zhinan', '马尔代夫钓鱼季节：逐月指南', '从东北季风期的金枪鱼和梭鱼季节，到随后的巨鲹季节——马尔代夫环礁每种鱼类的最佳捕捞时间。', null, '<p>马尔代夫的钓鱼条件会随着该国两个季风季节的变化而变化，吸引钓鱼爱好者前来的几种鱼类在这一周期中各自都有自己的季节。本指南依据我们整个<a href="/maldives/fishing/">马尔代夫钓鱼指南</a>中使用的相同鱼种数据，展示实际最佳的捕捞时机。</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-liveaboard-maldives.webp" alt="马尔代夫钓鱼潜水船" loading="lazy" /></figure><h2>两个季风季节</h2><p>马尔代夫属于热带季风气候，有两个主要季节。当地称为“Iruvai”的东北季风大约从12月持续到4月，海面更为平静，降雨较少，是各类海上行程最可预测的时段。西南季风“Hulhangu”大约从5月持续到11月，降雨较多，某些天气海面较为动荡，不过整个期间行程仍在继续，而一些最受欢迎的运动钓鱼鱼种在这一时期反而更为活跃。</p><h2>各鱼种最佳季节</h2><p>以下是我们<a href="/maldives/fishing/#fish-species">鱼种指南</a>中所涵盖鱼类的季节性规律：</p><ul><li><strong>黄鳍金枪鱼</strong>——12月至3月，东北季风较平静的时期。</li><li><strong>梭鱼</strong>——12月至3月，同一时段，通常用拖钓方式捕获。</li><li><strong>鲯鳅（鬼头刀）</strong>——12月至4月，常见于漂浮物和集鱼装置（FAD）附近。</li><li><strong>牙带鱼</strong>——11月至4月，在更深的陡坡和礁石斜坡处。</li><li><strong>巨鲹</strong>——4月至10月，涵盖向西南季风过渡的时期。</li><li><strong>鲣鱼</strong>——全年皆可，是马尔代夫传统竿线捕鱼业的基础。</li></ul><h2>12月至4月：东北季风季节</h2><p>这是黄鳍金枪鱼、梭鱼和鲯鳅同时当季的时期，海面更平静，不仅让出海的日子更加舒适，也让沿着环礁边缘拖钓的条件更加理想。</p><figure><img src="legacy/fishing/images/yellowfin-tuna.webp" alt="马尔代夫的黄鳍金枪鱼" loading="lazy" /></figure><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="马尔代夫的梭鱼" loading="lazy" /></figure><h2>4月至10月：巨鲹季节</h2><p>随着季节转向西南季风，巨鲹季节随之到来。GT被认为是马尔代夫运动钓鱼中标志性的目标鱼种，巡游于礁石边缘和水道之间，以其爆发性的攻击而著称——马尔代夫被认为是全球捕获战利品级巨鲹的顶级钓场之一。</p><figure><img src="legacy/images/fishing/giant-trevally-fish.webp" alt="马尔代夫的巨鲹" loading="lazy" /></figure><h2>按季节预订</h2><p>我们自营的<a href="/maldives/providers/maldives-fishing-and-holiday/">包船业务</a>全年提供从加夫阿利夫环礁马门杜出发、使用“Emperor”号的私人包船——欲了解最新价格，请查看我们的<a href="/maldives/fishing/private-full-day-fishing-charter/">全天</a>和<a href="/maldives/fishing/private-half-day-fishing-charter/">半天</a>包船页面，或阅读我们的<a href="/maldives/travel-guide/gaafu-atoll-fishing-guide-mfh-maamendhoo/">加夫环礁钓鱼指南</a>全文。</p>', '马尔代夫钓鱼季节：逐月指南 | 马尔代夫旅行指南 | MTG', '从东北季风期的金枪鱼和梭鱼季节，到随后的巨鲹季节——马尔代夫环礁每种鱼类的最佳捕捞时间。', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'where-is-maldives-located'), 'article', 'zh', 'maldives-weiyu-hechu', '马尔代夫位于哪里？', '马尔代夫位于哪里？了解这个热带天堂的地理位置，以及为何它是全球旅行者钟爱的目的地之一。', null, '<h2>马尔代夫位置概述</h2><p>马尔代夫，正式名称为马尔代夫共和国，是位于印度洋中的一个热带天堂。马尔代夫位于斯里兰卡和印度的西南方，是由26个环礁、超过1000座珊瑚岛组成的岛链。这个美丽的国家以其令人惊叹的白色沙滩、清澈的碧绿海水和色彩斑斓的珊瑚礁而闻名，是追求宁静与自然之美的旅行者向往的目的地。</p><h2>马尔代夫地图</h2><h2>地理坐标</h2><figure><img src="legacy/images/maps/maldives-location-map.webp" alt="马尔代夫位置地图" loading="lazy" /></figure><p>马尔代夫地理位置优越，大约位于赤道以北7度处，全年保持温暖的热带气候。马尔代夫的地理坐标大约为北纬3°15′，东经73°00′。这一位置使马尔代夫位于印度洋中心，远离任何大型陆地，这也造就了其与世隔绝、宁静祥和的氛围。</p><h2>与邻国的距离</h2><figure><img src="legacy/images/maps/location-of-maldives.webp" alt="马尔代夫的位置" loading="lazy" /></figure><p>马尔代夫位于斯里兰卡西南约700公里处，印度西南约400公里处。由于靠近南亚，从科伦坡、孟买和班加罗尔等该地区主要城市乘飞机可轻松抵达马尔代夫。首都<a href="/maldives/islands/male/">马累</a>位于其中一座岛屿上，设有国际机场，是马尔代夫连接世界的主要门户。</p><h2>马尔代夫的环礁</h2><figure><img src="legacy/images/maps/maldives-atoll-map.webp" alt="马尔代夫环礁地图" loading="lazy" /></figure><p>马尔代夫由26个自然环礁组成，分布在约90,000平方公里的范围内。这些环礁被划分为20个行政区域，每个区域由众多小岛组成。马尔代夫独特之处在于其陆地面积相对较小，却占据着广阔的海洋区域。马尔代夫最大的环礁是巴阿环礁，它同时也是联合国教科文组织生物圈保护区，以其丰富的生物多样性和未受破坏的海洋环境而闻名。</p><h2>马尔代夫位置的重要性</h2><figure><img src="legacy/images/maps/indian-ocean.webp" alt="马尔代夫位置的重要性" loading="lazy" /></figure><p>马尔代夫的地理位置之所以重要，有以下几个原因。首先，靠近赤道意味着全年气候温暖、阳光充足，是海滩爱好者和水上运动爱好者的理想目的地。其次，马尔代夫身处印度洋中央、与世隔绝的地理位置，营造出一种远离尘嚣、独享专属的氛围，深受寻求宁静假期的游客喜爱。最后，周围海域拥有世界上最美丽的部分珊瑚礁和海洋生物，使马尔代夫成为浮潜和潜水的顶级目的地。</p><h2>如何前往马尔代夫</h2><p>由于有来自全球多个主要城市的直飞航班，前往马尔代夫相对简单。大多数游客抵达位于首都马累附近胡鲁雷岛的维拉纳国际机场。从那里，旅行者根据与机场的距离，乘坐快艇、水上飞机或国内航班前往各自的度假岛屿。马尔代夫与世隔绝的地理位置意味着，抵达后您将被大海的宁静所包围，耳边只有海浪的声音。</p><h2>结语：遗世独立的热带天堂</h2><p>马尔代夫身处印度洋中央的地理位置，使其成为一个真正独特的目的地。其地理位置与自然之美及宁静氛围相结合，吸引着来自世界各地的游客。无论您计划的是浪漫之旅、家庭假期，还是充满冒险的假期，马尔代夫都能在这片地球上最美丽的地方之一，为每个人提供属于自己的体验。</p>', '马尔代夫位于哪里？ | 马尔代夫旅行指南 | MTG', '马尔代夫位于哪里？了解这个热带天堂的地理位置，以及为何它是全球旅行者钟爱的目的地之一。', 'published', 'claude')
